'use strict';

const headers = [
    'x-ya-user-ticket',
    'x-ya-service-ticket',
    'ticket',
];

/**
 * Обфусцирует заголовки с TVM тикетами.
 *
 * Пример подключения:
 *   require('@yandex-int/yandex-logger/middleware/secure-tvm-headers')({
 *       field: 'req.headers'
 *   });
 *
 * Пример лога:
 *   logger.info({ req: { headers: { 'x-ya-service-ticket': 'asdasdasdasd' }}}
 *
 *   output:
 *      {"req":{"headers":{"x-ya-service-ticket":"asdasdXXXXXX"}}}
 *
 * @param {Object} [config]
 * @returns {Function}
 * @see https://wiki.yandex-team.ru/logfeller/security/
 */
module.exports = config => {
    config = config || {};

    let field = config.field || 'req.headers';

    return require('./secure-field')({
        fields: headers.map(header => `${field}.${header}`),
    });
};
